package com.mendhak.gpslogger.loggers;

import android.content.Context;
import android.widget.Toast;
import com.mendhak.gpslogger.common.events.ServiceEvents;
import de.greenrobot.event.EventBus;

/**
 * Shared utility for reporting file write errors from background logger threads.
 * Posts EventBus events so the main activity can show user-visible notifications.
 */
public class LoggerErrorHandler {

    private final Context applicationContext;

    public LoggerErrorHandler(Context applicationContext) {
        this.applicationContext = applicationContext.getApplicationContext();
    }

    /**
     * Report a file write error: log it, post an EventBus event, and show a Toast.
     *
     * @param loggerName Name of the logger that failed (e.g., "GPX", "KML", "CSV")
     * @param errorMessage Human-readable error description
     */
    public void onFileWriteError(String loggerName, String errorMessage) {
        EventBus.getDefault().post(new ServiceEvents.FileWriteError(
                loggerName + ": " + errorMessage));

        if (applicationContext != null) {
            Toast.makeText(applicationContext,
                    com.mendhak.gpslogger.R.string.file_write_error,
                    Toast.LENGTH_LONG).show();
        }
    }
}

